function P(id,name,cat,shape,pos,dim,f,c,e,d,r,v,extra){
  const o={id,name,cat,shape,pos,f,c,e,d,r,v};
  if(shape==='box') o.size=dim; else {o.radius=dim[0]; o.height=dim[1]; o.rotAxis=dim[2];}
  return Object.assign(o,extra||{});
}
